#include "stdlib/blas/ext/base/ndarray/caxpby.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/real.h"
#include "stdlib/complex/float32/imag.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>

int main( void ) {
	// Create data buffers:
	const float dataX[] = { 1.0f, -2.0f, 3.0f, -4.0f, 5.0f, -6.0f, 7.0f, -8.0f, 9.0f, -10.0f, 11.0f, -12.0f, 13.0f, -14.0f, 15.0f, -16.0f };
	float dataY[] = { 2.0f, 3.0f, 4.0f, 5.0f, 6.0f, 7.0f, 8.0f, 9.0f, 10.0f, 11.0f, 12.0f, 13.0f, 14.0f, 15.0f, 16.0f, 17.0f };

	// Specify the number of array dimensions:
	const int64_t ndims = 1;

	// Specify the array shape:
	int64_t shape[] = { 8 };

	// Specify the array strides:
	int64_t strides[] = { STDLIB_NDARRAY_COMPLEX64_BYTES_PER_ELEMENT };

	// Specify the byte offset:
	const int64_t offset = 0;

	// Specify the array order:
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;

	// Specify the index mode:
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;

	// Specify the subscript index modes:
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	const int64_t nsubmodes = 1;

	// Create an ndarray for x:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *x = stdlib_ndarray_allocate( STDLIB_NDARRAY_COMPLEX64, (uint8_t *)dataX, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );

	// Create an ndarray for y:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *y = stdlib_ndarray_allocate( STDLIB_NDARRAY_COMPLEX64, (uint8_t *)dataY, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );

	// Create a data buffer for an ndarray containing the scalar constant alpha:
	const float adata[] = { 2.0f, 1.0f };

	// Specify the array strides for a zero-dimensional ndarray:
	int64_t astrides[] = { 0 };

	// Create an ndarray containing the scalar constant alpha:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *alpha = stdlib_ndarray_allocate( STDLIB_NDARRAY_COMPLEX64, (uint8_t *)adata, 0, NULL, astrides, 0, order, imode, nsubmodes, submodes );

	// Create a data buffer for an ndarray containing the scalar constant beta:
	const float bdata[] = { 1.0f, -1.0f };

	// Specify the array strides for a zero-dimensional ndarray:
	int64_t bstrides[] = { 0 };

	// Create an ndarray containing the scalar constant beta:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *beta = stdlib_ndarray_allocate( STDLIB_NDARRAY_COMPLEX64, (uint8_t *)bdata, 0, NULL, bstrides, 0, order, imode, nsubmodes, submodes );

	if ( x == NULL || y == NULL || alpha == NULL || beta == NULL ) {
		fprintf( stderr, "Error allocating memory.\n" );
		exit( 1 );
	}

	// Define a list of ndarrays:
	const struct ndarray *arrays[] = { x, y, alpha, beta };

	// Perform computation:
	stdlib_blas_ext_caxpby( arrays );

	// Print the result:
	// cppcheck-suppress invalidPointerCast
	const stdlib_complex64_t *v = (const stdlib_complex64_t *)dataY;
	for ( int i = 0; i < 8; i++ ) {
		printf( "y[ %i ] = %f + %fi\n", i, stdlib_complex64_real( v[ i ] ), stdlib_complex64_imag( v[ i ] ) );
	}

	// Free allocated memory:
	stdlib_ndarray_free( x );
	stdlib_ndarray_free( y );
	stdlib_ndarray_free( alpha );
	stdlib_ndarray_free( beta );
}
